// ─── File: src/test/java/com/bank/chm/ConcurrentHashMapInternalsTest.java ───
package com.bank.chm;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;

class ConcurrentHashMapInternalsTest {

    // ═══ Lock-free reads + concurrent writes ═══
    @Test
    void concurrentReadsAndWrites() throws InterruptedException {
        ConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();
        int threads = 10, opsPerThread = 50_000;
        CountDownLatch latch = new CountDownLatch(threads * 2);  // readers + writers

        // Writers:
        for (int t = 0; t < threads; t++) {
            final int threadId = t;
            new Thread(() -> {
                for (int i = 0; i < opsPerThread; i++) {
                    map.put("key-" + threadId + "-" + i, i);
                }
                latch.countDown();
            }).start();
        }

        // Readers (concurrent with writers):
        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                for (int i = 0; i < opsPerThread; i++) {
                    map.get("key-0-" + i);  // lock-free read!
                }
                latch.countDown();
            }).start();
        }

        latch.await(30, TimeUnit.SECONDS);
        assertThat(map).hasSize(threads * opsPerThread);  // all entries present!
    }

    // ═══ Atomic compute operations ═══
    @Test
    void atomicCompute_noConcurrencyBugs() throws InterruptedException {
        ConcurrentHashMap<String, AtomicInteger> map = new ConcurrentHashMap<>();
        map.put("counter", new AtomicInteger(0));

        int threads = 20, incrementsPerThread = 10_000;
        ExecutorService pool = Executors.newFixedThreadPool(threads);

        for (int t = 0; t < threads; t++) {
            pool.submit(() -> {
                for (int i = 0; i < incrementsPerThread; i++) {
                    map.get("counter").incrementAndGet();
                }
            });
        }

        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
        assertThat(map.get("counter").get()).isEqualTo(threads * incrementsPerThread);
    }

    // ═══ computeIfAbsent — atomic lazy init ═══
    @Test
    void computeIfAbsent_atomic() throws InterruptedException {
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        AtomicInteger loadCount = new AtomicInteger(0);

        // 10 threads all try to load the same key simultaneously:
        ExecutorService pool = Executors.newFixedThreadPool(10);
        for (int t = 0; t < 10; t++) {
            pool.submit(() -> {
                cache.computeIfAbsent("SAV2001", k -> {
                    loadCount.incrementAndGet();
                    return "Rajesh";  // expensive DB load — should happen ONCE!
                });
            });
        }

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
        assertThat(cache.get("SAV2001")).isEqualTo("Rajesh");
        assertThat(loadCount.get()).isEqualTo(1);  // loaded ONCE! Atomic!
    }

    // ═══ No null allowed ═══
    @Test
    void nullNotAllowed() {
        ConcurrentHashMap<String, String> map = new ConcurrentHashMap<>();
        assertThatThrownBy(() -> map.put(null, "val")).isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> map.put("key", null)).isInstanceOf(NullPointerException.class);
    }
}
